const cfg = {
  url: $env.ODOO_URL,
  db: $env.ODOO_DB,
  user: $env.ODOO_USER,
  key: $env.ODOO_API_KEY,
  publicUrl: $env.ODOO_PUBLIC_URL || $env.ODOO_URL,
};
const rpc = async (service, method, args) => {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: `${cfg.url}/jsonrpc`,
    json: true,
    body: { jsonrpc: '2.0', method: 'call', params: { service, method, args } },
  });
  if (res.error) throw new Error(`Odoo: ${res.error.data?.message || res.error.message}`);
  return res.result;
};
const uid = await rpc('common', 'login', [cfg.db, cfg.user, cfg.key]);
if (!uid) throw new Error('Odoo: usuario o API key incorrectos');
const odoo = (model, method, args, kwargs = {}) =>
  rpc('object', 'execute_kw', [cfg.db, uid, cfg.key, model, method, args, kwargs]);

const leadId = Number($json.body?._id || $json.body?.id);
if (!leadId) throw new Error('El webhook no trae el ID de la oportunidad');

const [lead] = await odoo('crm.lead', 'read', [[leadId]],
  { fields: ['name', 'partner_id', 'user_id', 'service_type_id', 'project_id', 'desired_date'] });
if (!lead) throw new Error(`Oportunidad ${leadId} no encontrada`);

if (lead.project_id) {
  return { json: { lead_id: leadId, lead_nombre: lead.name, proyecto_existente: true, proyecto_id: lead.project_id[0] } };
}

const pedidos = await odoo('sale.order', 'search_read',
  [[['opportunity_id', '=', leadId], ['state', 'in', ['draft', 'sent', 'sale']]]],
  { fields: ['id', 'name', 'state'], order: 'state desc, id desc', limit: 1 });

let pedido = null;
let entregas = [];
if (pedidos.length) {
  const p = pedidos[0];
  if (p.state !== 'sale') await odoo('sale.order', 'action_confirm', [[p.id]]);
  [pedido] = await odoo('sale.order', 'read', [[p.id]], { fields: ['name', 'state', 'amount_total', 'picking_ids'] });
  if (pedido.picking_ids.length) {
    entregas = await odoo('stock.picking', 'read', [pedido.picking_ids], { fields: ['name', 'state'] });
  }
}

return {
  json: {
    lead_id: leadId,
    lead_nombre: lead.name,
    proyecto_existente: false,
    partner_id: lead.partner_id ? lead.partner_id[0] : null,
    cliente: lead.partner_id ? lead.partner_id[1] : null,
    user_id: lead.user_id ? lead.user_id[0] : null,
    service_type_id: lead.service_type_id ? lead.service_type_id[0] : null,
    tipo_servicio: lead.service_type_id ? lead.service_type_id[1] : null,
    pedido_id: pedido?.id || null,
    pedido: pedido?.name || null,
    pedido_estado: pedido?.state || null,
    entregas: entregas.map((e) => ({ id: e.id, nombre: e.name, estado: e.state })),
  },
};

const cfg = {
  url: $env.ODOO_URL,
  db: $env.ODOO_DB,
  user: $env.ODOO_USER,
  key: $env.ODOO_API_KEY,
  publicUrl: $env.ODOO_PUBLIC_URL || $env.ODOO_URL,
};
const rpc = async (service, method, args) => {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: `${cfg.url}/jsonrpc`,
    json: true,
    body: { jsonrpc: '2.0', method: 'call', params: { service, method, args } },
  });
  if (res.error) throw new Error(`Odoo: ${res.error.data?.message || res.error.message}`);
  return res.result;
};
const uid = await rpc('common', 'login', [cfg.db, cfg.user, cfg.key]);
if (!uid) throw new Error('Odoo: usuario o API key incorrectos');
const odoo = (model, method, args, kwargs = {}) =>
  rpc('object', 'execute_kw', [cfg.db, uid, cfg.key, model, method, args, kwargs]);

const s = $json;
const hoy = $now.setZone('America/Lima').startOf('day');

const plantilla = s.service_type_id
  ? await odoo('crm.service.type.task', 'search_read',
      [[['service_type_id', '=', s.service_type_id]]],
      { fields: ['name', 'days_offset', 'user_id', 'description'], order: 'sequence, id' })
  : [];

const habil = (fecha) => {
  let f = fecha;
  while (f.weekday > 5) f = f.plus({ days: 1 });
  return f;
};

const plazoFinal = habil(hoy.plus({ days: Math.max(0, ...plantilla.map((t) => t.days_offset)) }));
const proyectoId = await odoo('project.project', 'create', [{
  name: s.lead_nombre,
  partner_id: s.partner_id || false,
  user_id: s.user_id || false,
  date_start: hoy.toISODate(),
  date: plazoFinal.toISODate(),
  description: `<p>Oportunidad ganada${s.pedido ? `, pedido ${s.pedido}` : ''}.</p>`,
}]);

const tareas = [];
for (const t of plantilla) {
  const limite = habil(hoy.plus({ days: t.days_offset })).set({ hour: 18 }).toUTC();
  const responsable = t.user_id ? t.user_id[0] : s.user_id;
  tareas.push(await odoo('project.task', 'create', [{
    project_id: proyectoId,
    name: t.name,
    user_ids: [[6, 0, responsable ? [responsable] : []]],
    date_deadline: limite.toFormat('yyyy-MM-dd HH:mm:ss'),
    partner_id: s.partner_id || false,
    description: t.description || false,
  }]));
}

await odoo('crm.lead', 'write', [[s.lead_id], { project_id: proyectoId }]);
await odoo('crm.lead', 'message_post', [[s.lead_id]], {
  body: `Proyecto creado con ${tareas.length} tareas${s.pedido ? `. Pedido ${s.pedido} confirmado` : ''}.`,
  message_type: 'comment',
  subtype_xmlid: 'mail.mt_note',
});

return {
  json: {
    ...s,
    proyecto_id: proyectoId,
    tareas: tareas.length,
    fecha_fin: plazoFinal.toISODate(),
    entregas_texto: s.entregas.map((e) => e.nombre).join(', '),
    enlace_proyecto: `${cfg.publicUrl}/odoo/project/${proyectoId}/tasks`,
    enlace_oportunidad: `${cfg.publicUrl}/odoo/action-crm.crm_lead_action_pipeline/${s.lead_id}`,
  },
};

